// Generated by scripts/split-i18n.js. Do not edit by hand.
import type { TopicText } from '../types';
const table: Record<string, TopicText> = {"t00":{"title":"Driving licence and its categories","blocks":[{"text":"Private: age 18 or over (a temporary permit for a maximum of one year from age 17), completing training at a driving school, passing the theory and practical tests, paying the fees, and settling any previous violations."},{"text":"The private licence is valid for up to 10 years and allows carrying a maximum of 9 people including the driver, and driving small vehicles weighing no more than 3500 kg."},{"text":"Public: age 20 or over, valid for 5 years. Category 1: taxi (up to 8 passengers); Category 2: light transport (up to 3500 kg) or heavy transport (more than that); Category 3: buses (small: 15 passengers or fewer; large: more)."},{"text":"Public works vehicles: age 20, valid for 5 years. Motorcycle: age 18, valid for 10 years."},{"text":"Non-Saudis must have legal residency, be free of diseases and disabilities that prevent driving, and have no court ruling for certain crimes (assault or drugs) unless their record has been officially cleared."},{"text":"The licence contains: name, ID number, date of birth, restrictions, sex, blood group, issue and expiry dates, and nationality."}]},"t01":{"title":"Speed and stopping distance","blocks":[{"text":"Always adjust your speed to the conditions so that you can stop in time. Speed, and failing to adjust it, is a major cause of road accidents."},{"text":"Stopping distance = reaction distance + braking distance. The usual reaction time is one second."},{"text":"Reaction distance (m) = (speed ÷ 10) × 3 · Braking distance (m) = (speed ÷ 10) × (speed ÷ 10) on a dry road."},{"table":[["Speed (km/h)","Reaction (m)","Braking (m)","Stopping (m)"],["30","9","9","18"],["50","15","25","40"],["60","18","36","54"],["80","24","64","88"],["100","30","100","130"],["120","36","144","180"]]},{"text":"Reaction distance gets longer with high speed, distraction and fatigue, and drugs, alcohol or medicines that cause drowsiness."},{"text":"Braking distance gets longer with speed, a heavy load, poor road conditions (sand, wet surface), and poor tyres or brakes."},{"text":"To reduce it: slow down, pay more attention, and rest your foot over the brake pedal without pressing."},{"text":"If your speed is just 10 km/h higher (from 50 to 60), you may hit at about 40 km/h instead of stopping, and the impact is like falling from a height of 6.5 metres without a seat belt."}]},"t02":{"title":"Traffic accidents","blocks":[{"text":"Reasons for the high number of accidents: speeding, not following the rules, using a mobile phone and not wearing a seat belt, sudden lane changes, and the condition of the vehicle and the road."},{"text":"Minor accident: damage not exceeding 5,000 SAR or an injury that does not require hospital treatment. Major accident: deaths or serious injuries."},{"text":"Legal liability depends on the share of fault: 100%, 75%, 50% or 25%."},{"text":"In an accident with injuries: call the traffic police (993 / 911) and the Red Crescent (997). In an accident with damage only: use the Najm app and photograph the accident from all angles."},{"text":"Do not move the vehicles unless they block traffic or threaten safety, or the accident is minor and both parties agree."},{"text":"Leaving the accident scene without a reason counts as fleeing. The penalty can reach 2,000 SAR and/or 3 months in prison. Detention in accidents involving death or serious injury does not exceed 72 hours."}]},"t03":{"title":"Violations and fines","blocks":[{"table":[["Category","Fine (SAR)","Examples"],["1","100–150","Parking outside designated places, no valid insurance"],["2","150–300","Not using the indicator, not wearing a seat belt, not carrying the licence, not keeping a safe distance, reversing more than 20 m"],["3","300–500","Being distracted from the road, sudden braking, expired licence, not using a child seat"],["4","500–900","Not stopping at a \"Stop\" sign, right-of-way violation, phone in hand, driving in a tunnel without lights"],["5","1,000–2,000","Stopping on a railway line, driving without a front plate, overtaking where prohibited, not wearing a helmet"],["6","3,000–6,000","Running a red light, overtaking a school bus, driving against traffic, racing"],["7","5,000–10,000","Driving under the influence of alcohol or drugs, plates that do not belong to the vehicle"]]},{"text":"Speeding fines by how far over the limit you drive:"},{"table":[["Over the limit (km/h)","Roads up to 120 km/h (SAR)","Roads at 140 km/h (SAR)"],["5–10","—","300–500"],["10–20","150–300","800–1,000"],["20–30","300–500","1,200–1,500"],["30–40","800–1,000","1,500–2,000"],["40–50","1,200–1,500","1,500–2,000"],["More than 50","1,500–2,000","1,500–2,000"]]},{"text":"Drifting (tafheet): first time, vehicle impounded for 15 days and a 20,000 SAR fine; second time, one month and 40,000; third time, vehicle confiscated and 60,000."},{"text":"The violator stays inside their vehicle until the traffic officer arrives. The minimum fine can be paid within 30 days; after that the maximum applies. Check and pay through Absher."}]},"t04":{"title":"Violation points and licence suspension","blocks":[{"table":[["Points","Violation"],["24","Driving under the influence of alcohol or drugs"],["24","Drifting (tafheet)"],["12","Not stopping at a red light"],["12","Driving against the direction of traffic"],["8","Reckless driving between vehicles"],["8","Not obeying a traffic officer's instructions"],["8","Driving a vehicle without brakes or lights"],["6","Not coming to a complete stop at a \"Stop\" sign"],["6","Not respecting the right of way"],["6","Exceeding the speed limit by more than 25 km/h"],["6","Not giving way at a roundabout"],["6","Overtaking in prohibited places"],["6","Stopping on railway tracks"],["4","Exceeding the speed limit by no more than 25 km/h"],["4","Driving in lanes not designated for the vehicle"],["4","Overtaking a school bus while students are getting on or off"],["4","Not covering or securing loads"],["4","Modifying the body without official procedures"],["2","Not wearing a seat belt"],["2","Using a hand-held mobile phone"],["2","Not wearing a helmet on a motorcycle"]]},{"text":"On reaching 24 points the licence is suspended: the first time in a Hijri year for 3 months, the second for 6 months, the third for one year, and the fourth is permanent revocation."},{"text":"Driving while the licence is suspended is referred to court, and the driver may be required to take a 15-day rehabilitation programme. After permanent revocation, the driver can apply for a new licence after one year, with a one-month rehabilitation programme and passing both tests."}]},"t05":{"title":"Parts of the road and guide signs","blocks":[{"text":"A main road is entered and exited through entrances and exits, and a service road serves the adjacent properties. The traffic island (median) separates the two directions, and the merging lane lets you join the road's traffic."},{"text":"Guide signs: blue with white letters (cities and villages outside the city), green (streets and districts inside cities), white with black letters (important facilities such as airports), brown (farms, resorts, museums and religious places)."},{"text":"Temporary work zone signs have the same shapes but are yellow with a red border."}]},"t06":{"title":"Road users and behaviour","blocks":[{"text":"Rules of behaviour: drive safely, respectfully, cautiously and lawfully, and obey traffic officers' orders even if they contradict the usual rules (e.g. a green light while a traffic officer orders you to stop)."},{"text":"Pedestrians: a steady green allows crossing, a flashing green means red is about to come so the road must be cleared, and red prohibits crossing. At pedestrian crossings, reduce speed, be ready to stop and do not obstruct anyone who has started crossing."},{"text":"Emergency vehicles: give way immediately, do not follow them closer than 50 m, do not pull out of parking spaces before they pass, and clear intersections."},{"text":"School buses: they stop for students to get on and off, and overtaking them while they are stopped is prohibited."},{"text":"Official motorcades: give way to them and do not cut through them."},{"text":"Assess the people around you by age, attentiveness and intention. Children act spontaneously and do not judge danger, and elderly people may become confused and have poor hearing or eyesight. If you are not sure, make eye contact."}]},"t07":{"title":"Driver obligations and prohibitions","blocks":[{"text":"Do not drive while injured, ill, exhausted, distracted or agitated, or under the influence of alcohol, drugs or medication (read the medicine leaflet)."},{"text":"Before driving: clean the windows, lights and mirrors; check the tyres, lights and brakes; adjust your seating position and mirrors, and fasten your seat belt."},{"text":"While driving: stay on the paved part of the road, in the appropriate lane and within the permitted speed, and signal before turning."},{"text":"Prohibited: hazard lights except in emergencies, switching off the engine while moving, noise, curtains and advertisements on the vehicle, letting the vehicle roll, carrying people outside their seats, washing the vehicle on a public road, throwing litter, and taking part in processions without permission."},{"text":"In case of a breakdown: clear the road and secure the vehicle. By day, place a warning triangle at the stopping distance; at night, add red lights."},{"text":"When leaving the vehicle: switch off the engine, remove the key and lock the vehicle, and open the doors carefully on the kerb side."}]},"t08":{"title":"Carrying passengers and seat belts","blocks":[{"text":"Passengers may only be carried in vehicles designed for them; it is prohibited to carry them in the vehicle's rear cargo bed, on any external part, or in trucks."},{"text":"Seat belts are mandatory for the driver and all passengers, and the driver must remind passengers. Exemptions are for health reasons with medical proof and official permission, or because of body size."},{"text":"Children under 12 need a booster seat so that the belt sits below the shoulder. A child under 10 may not sit in the front seat unless there are no rear seats (and with a suitable child seat)."},{"text":"Leaving children under 10 in the vehicle without an adult is a violation."}]},"t09":{"title":"Driving and changing lanes","blocks":[{"text":"On a two-lane road with a broken line: use the right lane and do not cross the line except to overtake. Crossing a double solid line is prohibited."},{"text":"On multi-lane roads, slow vehicles keep to the far right unless they are preparing to turn left."},{"text":"Keep to the far right if you want to turn right, if vehicles are overtaking you, if your speed is lower, if visibility is poor, or if vehicles are coming from the opposite direction."},{"text":"Driving on the left is permitted to overtake, to avoid an accident, or if part of the right side is closed by signs or officials."},{"text":"Narrow sections (bottlenecks): keep right and leave side clearance for oncoming traffic, stop if necessary, and use the horn only when necessary."},{"text":"Changing lanes: mirrors → signal → shoulder check (blind spot) → adjust speed → move smoothly. The higher the speed, the smoother the steering must be."},{"text":"Relying only on the side mirrors leaves you exposed to the blind spot, so look over your shoulder."}]},"t10":{"title":"Turning, roundabouts and reversing","blocks":[{"text":"Without markings: turn right from the far right with a tight curve. Turn left from the middle of the road (to the right of the dividing line) on two-way roads, and from the far left on one-way roads, with a wide curve. Where there are arrows, use the lane marked with the arrow for your direction."},{"text":"Plan ahead and choose the correct lane before the intersection, signal early and slow down without sudden braking."},{"text":"Roundabout: vehicles inside it have priority. To turn right use the right-hand (first) lane, to turn left use the left-hand (third) lane, and signal right before your exit. For the second exit, signal at the island of the first exit; for a U-turn, signal at the island of the second exit."},{"text":"Reverse only when necessary and for no more than 20 m. Reversing is prohibited on highways."},{"text":"U-turns are allowed at intersections unless a sign prohibits them."}]},"t11":{"title":"Traffic lights and intersections","blocks":[{"text":"Red: stop at the stop line or where you can see the light, and do not cross the pedestrian crossing. Green: move off carefully and do not enter the intersection if you will get stuck in it. Amber: pay attention and stop if you can do so safely."},{"text":"A flashing amber light means the same as a \"Give way\" sign. A flashing red light means the same as a \"Stop\" sign."},{"text":"Turning right on red: from the far-right lane, with the right indicator on, after stopping for 2–3 seconds, and at less than 15 km/h. It is not allowed if there is a dedicated right-turn lane or a sign prohibiting it."},{"text":"A photo from an automated (Saher) camera does not mean an automatic penalty, as every photo is reviewed manually."},{"text":"A traffic police officer has the highest priority, so stop completely and look in all directions for 3 seconds."}]},"t12":{"title":"Right-of-way rules","blocks":[{"text":"Emergency vehicles always have priority."},{"text":"Equal intersection: priority goes to the vehicle closest to the intersection; if both arrive together, to the one coming from the right."},{"text":"A vehicle going straight ahead has priority over one changing direction (turning left or making a U-turn)."},{"text":"Partly blocked road: priority goes to the driver whose side of the road ahead (the right side) is open."},{"text":"Steep slope: the vehicle going downhill keeps close to the right edge and lets the vehicle going uphill pass, stopping if necessary."},{"text":"The main road has priority over a side road, and anyone entering from a side road must give way. A vehicle leaving the main road for a service road has priority."},{"text":"Unclear situation: make eye contact and give up your right of way if that helps safety."},{"text":"Do not enter an intersection if you will get stuck in it, even if the light is green."}]},"t13":{"title":"Railway crossings","blocks":[{"text":"The train has priority, and the driver must clear the track immediately when a train approaches. Stopping on the track is prohibited."},{"text":"Stop before the X sign when the light is red or amber, when the barriers are moving or closed, when the attendant signals, or if traffic does not allow you to finish crossing."},{"text":"Wait until the barriers are fully open and the red light is off, and make sure no train is approaching."}]},"t14":{"title":"Speed and safe distance","blocks":[{"text":"Small vehicles: follow the speed limit posted on the road; large vehicles: 50 km/h maximum inside cities. The sign shows the maximum limit, not a required speed."},{"text":"Reduce speed at intersections, crossings, on slippery roads and bends, in congestion, near pedestrians and animals, and in sandstorms, fog and rain."},{"text":"Keep a safety gap of at least two seconds behind the vehicle in front. Choose a reference point and count \"one thousand and one, one thousand and two\" after the vehicle ahead passes it. Increase the gap in bad weather, with heavy loads and behind motorcycles."},{"text":"Economical driving: look ahead and lift your foot off the accelerator early to slow down without braking, which reduces fuel consumption and brake wear. Avoid unnecessary stops."},{"text":"Unnecessary sudden braking and driving so slowly that it obstructs traffic are prohibited."}]}};
export default table;
